e.push(A.Fg("Kiapo cha Rais \xb7 Presidential Oath of Leadership",B.Q,k,11,B.dw,B.X,0.024,"subtitle",0.83,0.085,0.1))
e.push(A.dV2(0,0.002,B.eu,k,1.6,"title_rule",0.5312,0.2344,0.128))
e.push(A.eqG("body_p1",0.085,0.145,0.83,0.105,12,l,"Mimi [Jina Kamili la Rais], nikiwa Rais wa jamii yetu ya Kikongo, ninasimama mbele ya wanajamii wote kuapa kwamba nitawaongoza kwa haki, amani, na heshima kubwa, huku nikihakikisha tunashirikiana kwa pamoja kujenga jamii yetu na kuchangia maendeleo kwa njia bora na ya kistaarabu."))
